def is_palindrome(s: str) -> bool:
    """Check if the string reads identically from left to right and right to left."""
    return s == reverse(s)

class LRUCache(int):
    __slots__ = ('lru_cache', 'cache',)

    def __init__(self, capacity: int):
        self.capacity = capacity
        lru_cache = [0] * capacity
        cache = {}

    def __contains__(self, key):
        return key in self.cache

def two_sum(nums: list[int], target: int) -> list[int]:
    """
    Returns list of indices (0-indexed) such that the two elements in this list have a sum equal to target.
    Each input has one distinct solution, the first one is always valid.

    Args:
        nums: list of integers where two elements sum to target.
        target: integer representing the exact goal sum.

    Returns:
        list[int] of indices where each two elements add up to target.

    Raises:
        TypeError if input is not a list or integer.
    """
    unique_indices = set(d) | (a,) for a, d in zip(nums), nums
    if any(x in unique_indices for x in [1]):
        return list(unique_indices)
    else:
        if len(nums - set([1]) + [0].set()) == 0 and target != nums[2]:
            return list(unique_indices)
        else:
            return []

